function responseButtons(m,p,compact=false){const status=response(m,p)?.status||'pending',busy=pendingAnswers.has(recordId(m.id,p.id));return `<div class="rsvp-buttons ${compact?'compact':''}" role="group" aria-label="Disponibilità ${esc(p.name)}">${[['yes','✓','Ci sono'],['maybe','?','In dubbio'],['no','✕','Non ci sono']].map(([key,icon,label])=>`<button type="button" class="rsvp ${key} ${status===key?'chosen':''}" data-act="quick-${key}" data-id="${esc(JSON.stringify([m.id,p.id]))}" aria-pressed="${status===key}" ${busy?'disabled':''}><b>${icon}</b><span>${label}</span></button>`).join('')}</div>`;}
