function pendingReviewMatches(p){return D.matches.filter(m=>m.status==='played'&&participants(m).some(x=>x.id===p.id)).map(m=>({m,voted:(D.mvpVotes||[]).some(v=>v.matchId===m.id&&v.playerId===p.id),self:(D.selfVotes||[]).some(v=>v.matchId===m.id&&v.playerId===p.id)})).filter(x=>(x.m.mvpOpen&&!x.voted)||!x.self).sort((a,b)=>(b.m.date||'').localeCompare(a.m.date||''));}
