const STATUS={yes:'Disponibile',maybe:'In dubbio',no:'Assente',pending:'Non risposto'};
function legacyAvailability(){const ms=plannedMatches(),m=ms.find(m=>m.id===matchId)||ms[0];if(!m)return top('Presenze','Convocazioni e disponibilità')+empty('Nessuna partita programmata.');matchId=m.id;const ps=activePlayers(),own=myPlayer();return top('Presenze','Rispondi con un tocco · aggiornamento condiviso',staff()?button('+ Nuovo impegno','edit-match','','primary'):'')+`<div class="panel">${field('Impegno',select('match',ms.map(m=>[m.id,`${fmtDate(m.date)} ${m.time||''} · ${m.opponent}`]),m.id,'id="avail-match"'))}</div>${eventCard(m)}<div class="stack">${Object.keys(STATUS).map(k=>{const group=ps.filter(p=>(response(m,p)?.status||'pending')===k);return `<section class="panel stack"><h2 class="presence-heading ${k}">${STATUS[k]} · ${group.length}</h2>${group.length?group.map(p=>{const r=response(m,p),editable=staff()||own?.id===p.id;return `<div class="attendance-row"><div><strong>${esc(p.name)}${own?.id===p.id?' (tu)':''}</strong>${r?.note?`<p class="muted prewrap">${esc(r.note)}</p>`:''}</div>${editable?`<div class="attendance-actions">${responseButtons(m,p,true)}${button('Nota / stato','set-avail',p.id,'subtle')}</div>`:''}</div>`}).join(''):'<small>Nessun giocatore</small>'}</section>`}).join('')}</div>`;}
async function quickAnswer(status,id){const [mid,pid]=JSON.parse(id),m=match(mid),p=player(pid);if(!m||m.status!=='planned'||!p||p.active===false||(!staff()&&myPlayer()?.id!==pid))throw Error('Non puoi modificare questa disponibilità.');const key=recordId(mid,pid);if(pendingAnswers.has(key))return;pendingAnswers.add(key);render();try{await store.put('availability',key,{matchId:mid,playerId:pid,status,eventSchedule:m.date+' '+m.time,updatedAt:new Date().toISOString()});toast('Risposta salvata: '+STATUS[status]);}finally{pendingAnswers.delete(key);render();}}
function editAvail(id){const m=match(matchId),p=player(id);if(!m||m.status!=='planned'||!p||(!staff()&&myPlayer()?.id!==id))return;const r=D.availability.find(x=>x.id===recordId(m.id,id));modal('Disponibilità · '+p.name,`${field('Risposta',select('status',Object.entries(STATUS),r?.status||'pending'))}${field('Nota (facoltativa)',textarea('note',r?.note||'','maxlength="500"'))}`,async fd=>store.put('availability',recordId(m.id,id),{matchId:m.id,playerId:id,status:fd.get('status'),note:fd.get('note'),eventSchedule:m.date+' '+m.time,updatedAt:new Date().toISOString()}));}
function staffPage(){const ns=D.staffNotes.filter(n=>!n.archived||showArchived).sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||''));return top('Area staff','Appunti tecnici riservati a capitano, staff e amministratori',button(showArchived?'Nascondi archiviate':'Mostra archiviate','toggle-archived')+' '+button('+ Nota','edit-note','','primary'))+`<section class="panel stack"><h2>Proposte dei giocatori</h2>${isAdmin()?button('Migrazione valutazioni riservate','privacy-migrate','','primary'):''}<p>${privacyReady()?'Protezione valutazioni attiva':'Migrazione necessaria: accesso dati giocatori sospeso fino al completamento.'}</p><h3>Autovalutazioni riservate</h3>${(D.selfVotes||[]).map(v=>`<div>${esc(player(v.playerId)?.name||'')} · ${esc(match(v.matchId)?.opponent||'')} · ${v.score}/10 · ${esc(v.note||'')}</div>`).join('')||'Nessuna'}<h3>Highlights pubblicati</h3>${highlightList()}${(D.proFeedback||[]).map(r=>`<div><b>${esc(player(r.playerId)?.name||'Giocatore')}</b> · ${esc(r.kind)}<p>${esc(r.body)}</p>${r.kind==='highlight'?button('Pubblica highlight','highlight-approve',r.id):''}</div>`).join('')||'Nessuna proposta'}</section><div class="grid">${ns.length?ns.map(n=>`<article class="panel stack"><div class="line between"><h3>${esc(n.title)}${n.archived?' (archiviata)':''}</h3><small>${esc(n.category||'Generale')}</small></div>${n.playerId?`<span class="pill">${esc(player(n.playerId)?.name||'Giocatore')}</span>`:''}<p class="prewrap note">${esc(n.body)}</p><small>${esc(n.author||'')} · ${fmtDate(n.updatedAt?.slice(0,10))}</small>${button('Modifica','edit-note',n.id)}</article>`).join(''):empty('Nessun appunto riservato.')}</div>`;}
function editNote(id){const n=D.staffNotes.find(x=>x.id===id)||{id:uid(),title:'',body:'',playerId:'',category:'Generale'};modal('Nota riservata allo staff',`${field('Titolo',input('title',n.title,'text','required maxlength="100"'))}<div class="formgrid">${field('Categoria',select('category',['Generale','Tattica','Valutazione individuale','Proposta','Analisi avversario'].map(x=>[x,x]),n.category))}${field('Giocatore (facoltativo)',select('playerId',[['','Tutta la squadra'],...allPlayers().map(p=>[p.id,p.name])],n.playerId||''))}</div>${field('Appunti',textarea('body',n.body,'required maxlength="10000"'))}${field('Stato',select('archived',[['false','Attiva'],['true','Archiviata']],String(!!n.archived)))}`,async fd=>store.put('staffNotes',n.id,{title:fd.get('title'),category:fd.get('category'),playerId:fd.get('playerId'),body:fd.get('body'),archived:fd.get('archived')==='true',author:profile.name,updatedAt:new Date().toISOString()}));}
function users(){return top('Utenti e permessi','Approva gli accessi Google e associa ogni account alla rosa')+`<div class="panel stack"><p>Un nuovo utente accede con Google, poi resta in attesa finché non lo approvi. Collega il suo account a un giocatore per consentirgli di inviare disponibilità.</p>${D.users.length?table(['Nome','Email','Accesso','Giocatore collegato','Azioni'],D.users.slice().sort((a,b)=>(a.role==='pending'?0:1)-(b.role==='pending'?0:1)||sortName(a,b)).map(u=>[esc(u.name),esc(u.email),esc(ROLE_LABEL[u.role]||u.role),esc(player(u.playerId)?.name||'—'),button('Permessi','edit-user',u.id)])):empty('Nessun account.')}</div><div class="panel stack"><h2>Backup dei dati</h2><p class="muted">Scarica una copia JSON dei dati condivisi, comprese le note riservate e gli utenti. Conserva il file in un luogo sicuro: non caricarlo su GitHub pubblico.</p>${button('Scarica backup JSON','backup')}${demo?button('Ripristina dati demo','reset-demo','','danger'):''}</div>`;}
function editUser(id){const u=D.users.find(x=>x.id===id);if(!u)return;modal('Permessi · '+u.name,`${field('Ruolo',select('role',roleOptions,u.role,u.id===profile.id?'disabled':''))}${field('Scheda giocatore associata',select('playerId',[['','— Nessuna —'],...allPlayers().map(p=>[p.id,p.name])],u.playerId||''))}<p class="muted">Amministratore: gestione accessi e campi; capitano: gestione tecnica e approvazione formazioni; staff: gestione tecnica; giocatore: lettura e propria disponibilità; in attesa: nessun dato del club.</p>`,async fd=>{const playerId=fd.get('playerId');if(playerId&&D.users.some(x=>x.id!==u.id&&x.playerId===playerId&&x.role!=='pending'))throw Error('Questa scheda è già collegata a un altro account attivo.');await store.put('users',u.id,{role:u.id===profile.id?u.role:fd.get('role'),playerId});});}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCsv(){const fs=fieldDefs(),quote=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s)&&typeof v!=='number')s="'"+s;return '"'+s.replaceAll('"','""')+'"'};const rows=[['Giocatore','Presenze','Imbattibilità',...fs.map(f=>f.name)],...activePlayers().map(p=>[p.name,matchRecords(D,p.id).length,cleanSheets(p),...fs.map(f=>aggregate(D,p,f))])];download('the-boys-statistiche.csv','\ufeff'+rows.map(r=>r.map(quote).join(';')).join('\r\n'),'text/csv;charset=utf-8')}
async function handle(act,id){switch(act){case'award-edit':editCustomAward(id);break;case'build-active':await activateBuild(id);break;case'build-delete':await deleteBuild(id);break;case'privacy-migrate':await migratePrivacy();break;case'mvp-vote':await voteMvp(id);break;case'mvp-toggle':await toggleMvp(id);break;case'self-vote':await voteSelf(id);break;case'highlight-approve':await approveHighlight(id);break;case'highlight-hide':await hideHighlight(id);break;case'photo-edit':editPhoto();break;case'card-edition':chooseCard();break;case'objective-edit':editObjective(id);break;case'archive-player':await archivePlayer(id);break;case'build-edit':editProBuild(id);break;case'match-report':quickReport(id);break;case'edit-pro':editPro();break;case'add-build':editProBuild();break;case'pro-card':await proCard();break;case'pro-feedback':proFeedback();break;case'pro-highlight':proHighlight();break;case'pro-compare':comparePro();break;case'duplicate-match':if(staff())editMatch(id,'',true);break;case'remind-day':remindDay(id);break;case'day-history':showDayHistory(id);break;case'share-formation':await shareFormation(id);break;case'day-answer':editDay(id);break;case'day-all':await answerDayAll(id);break;case'day-current':weekOffset=0;render();break;case'day-prev':weekOffset--;render();break;case'day-next':weekOffset++;render();break;case'quick-yes':case'quick-maybe':case'quick-no':break;case'quick-form':{const m=match(id);if(m&&staff())editFormation(m.formationId||'',false,m.id);break;}case'nav':view=id;showArchived=false;render();break;case'login':await store.login();break;case'logout':await store.logout();break;case'toggle-archived':showArchived=!showArchived;render();break;case'player-profile':playerProfile(id);break;case'edit-player':editPlayer(id);break;case'edit-field':editField(id);break;case'archive-field':{const f=D.fields.find(f=>f.id===id);await saveField(id,{...f,archived:!f.archived});break;}case'defaults':{const base=DEFAULT_FIELDS.filter(([name])=>!D.fields.some(f=>f.name.toLowerCase()===name.toLowerCase()));if(!base.length){toast('I campi iniziali sono già presenti.');break;}for(const [i,[name,type,scope,aggregation,options]] of base.entries())await saveField(uid(),{name,type,scope,aggregation,options:options||[],order:D.fields.length+i,archived:false});toast('Campi aggiunti.');break;}case'toggle-sort':desc=!desc;render();break;case'csv':exportCsv();break;case'edit-match':editMatch(id);break;case'add-day-event':editMatch('',id);break;case'edit-day-plan':editDayPlan(id);break;case'share-day':shareDay(id);break;case'open-match':matchId=id;render();document.querySelector('#match-details')?.scrollIntoView({block:'start'});break;case'record':editRecord(id);break;case'remove-record':if(confirm('Eliminare la scheda e i relativi dati della partita?')){await store.remove('records',id);await store.remove('privateRecords',id);document.querySelector('#dialog').close();toast('Scheda eliminata.')}break;case'edit-formation':editFormation(id,false,D.matches.find(m=>m.formationId===id)?.id||'');break;case'duplicate-formation':editFormation(id,true);break;case'open-formation':formationId=id;render();break;case'go-form':view='formations';formationId=id;render();break;case'approve-formation':{const f=formation(id);await store.put('formations',id,{status:f.status==='approved'?'draft':'approved'});break;}case'go-avail':view='availability';matchId=id;weekOffset=0;const target=match(id);if(target){const monday=weekDays()[0];weekOffset=Math.floor((Date.parse(target.date)-Date.parse(monday))/604800000);}render();document.getElementById('event-'+id)?.scrollIntoView();break;case'set-avail':break;case'edit-note':editNote(id);break;case'edit-user':editUser(id);break;case'backup':download(`the-boys-backup-${today()}.json`,JSON.stringify({version:1,exportedAt:new Date().toISOString(),data:D},null,2),'application/json');break;case'reset-demo':if(confirm('Ripristinare gli esempi?'))store.reset();break;}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-act]');if(!b||b.disabled)return;b.disabled=true;try{await handle(b.dataset.act,b.dataset.id||'')}catch(err){toast(err.message||String(err),true)}finally{b.disabled=false}});document.addEventListener('change',e=>{if(e.target.id==='stat-sort'){sortField=e.target.value;render()}if(e.target.id==='avail-match'){matchId=e.target.value;render()}});
let weekOffset=0;
function dayResponse(date,p){return (D.dailyAvailability||[]).find(x=>x.date===date&&x.playerId===p.id);}
function weekDays(){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7)+weekOffset*7);return Array.from({length:7},(_,i)=>{const a=new Date(d);a.setDate(a.getDate()+i);return new Date(a-a.getTimezoneOffset()*60000).toISOString().slice(0,10)});}
function dayState(date,p){return dayResponse(date,p)?.status||'pending';}
const EVENT_TYPES={match:'Partita',training:'Allenamento',friendly:'Amichevole',meeting:'Riunione tattica',tournament:'Torneo',other:'Altro'};
const DAY_TYPES={collection:'Raccolta presenze',match:'Partita',training:'Allenamento',friendly:'Amichevole',meeting:'Riunione tattica',tournament:'Torneo',mixed:'Più eventi'};
function dayPlan(date){return (D.dayPlans||[]).find(p=>p.date===date);}
function dayEvents(date){return plannedMatches().filter(m=>m.date===date);}
function dayLabel(date,es){return DAY_TYPES[dayPlan(date)?.dayType]||'Raccolta presenze';}
function editDayPlan(date){if(!staff())return;const p=dayPlan(date)||{};modal('Programma del '+fmtDate(date),field('Programma indicativo della giornata',select('dayType',Object.entries(DAY_TYPES),p.dayType||'collection'))+field('Note e istruzioni generali',textarea('notes',p.notes||'','maxlength="5000"')),async fd=>{await store.put('matches','dayplan_'+date,{kind:'dayPlan',status:'day-plan',date,dayType:fd.get('dayType'),notes:fd.get('notes')});toast('Programma salvato.');});}
function shareDay(date){if(!staff())return;const es=dayEvents(date),p=dayPlan(date);const msg=['*THE BOYS 1927*',fmtDate(date)+' · '+dayLabel(date,es),p?.notes||'',...es.map(m=>[m.time||'Orario da definire',EVENT_TYPES[m.kind||'match']||'Evento',m.opponent,m.competition||'',m.notes||''].filter(Boolean).join(' · '))].filter(Boolean).join('\n');window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank','noopener,noreferrer');}
function availability(){return top('Presenze','Disponibilità giornaliere e per evento')+weeklyCalendar();}
function weeklyCalendar(){const own=myPlayer(),days=weekDays();return `<section class="stack"><div class="panel stack"><div class="line between"><h2>Disponibilità settimanale</h2><strong>${fmtDate(days[0])} – ${fmtDate(days[6])}</strong></div><div class="actions">${button('‹ Settimana','day-prev')}${button('Oggi','day-current')}${button('Settimana ›','day-next')}</div><small>Indica solo la tua disponibilità giornaliera. Gli orari sono facoltativi.</small></div>${days.map(date=>{const es=dayEvents(date),plan=dayPlan(date),counts=Object.keys(STATUS).map(k=>[k,activePlayers().filter(p=>dayState(date,p)===k).length]),r=own&&dayResponse(date,own);return `<section class="panel stack" id="day-${date}"><div class="line between"><div><h2>${esc(new Date(date+'T12:00:00').toLocaleDateString('it-IT',{weekday:'long',day:'numeric',month:'long'}))}${date===today()?' · Oggi':''}</h2><span class="pill">${esc(dayLabel(date,es))}</span></div><strong>${counts[0][1]}/${activePlayers().length} disponibili</strong></div>${plan?.notes?`<div class="notice prewrap">${esc(plan.notes)}</div>`:''}<div class="presence-totals">${counts.map(([k,n])=>`<span class="presence-count ${k}">${n} ${STATUS[k]}</span>`).join('')}</div>${own?`<div class="rsvp-buttons">${[['yes','✓','Ci sono'],['maybe','?','In dubbio'],['no','✕','Assente']].map(([k,i,l])=>`<button type="button" class="rsvp ${k} ${r?.status===k?'chosen':''}" data-act="day-all" data-id="${esc(JSON.stringify([date,k]))}"><b>${i}</b><span>${l}</span></button>`).join('')}</div><div class="line">${button('Indica orari','day-answer',date)}<small>${r?esc(STATUS[r.status]+(r.from?' dalle '+r.from:'')+(r.to?' fino alle '+r.to:'')):'Non hai ancora risposto alla giornata'}</small></div>`:'<small>Account non collegato alla rosa.</small>'}${staff()?`<div class="actions">${button('Programma / note','edit-day-plan',date)}${button('WhatsApp','share-day',date,'whatsapp')}${button('Sollecita','remind-day',date)}${button('Storico','day-history',date)}</div>`:''}<details><summary>Disponibilità dei compagni</summary>${roleCoverage({date})}${activePlayers().map(p=>{const x=dayResponse(date,p);return `<div>${esc(p.name)} · ${STATUS[dayState(date,p)]}${x?.from?' dalle '+esc(x.from):''}${x?.to?' fino alle '+esc(x.to):''}</div>`}).join('')}</details></section>`}).join('')}</section>`;}
async function saveDay(date,status,from='',to=''){const p=myPlayer();if(!p)throw Error('Account non associato alla rosa.');if(from&&to&&from>=to)throw Error('Controlla gli orari.');await store.saveDay(date+'_'+p.id,{date,playerId:p.id,status,from,to,updatedAt:new Date().toISOString()});toast('Disponibilità salvata.');}
async function answerDayAll(id){const [date,status]=JSON.parse(id);await saveDay(date,status);}
function editDay(date){const p=myPlayer();if(!p)return;const r=dayResponse(date,p)||{};modal('Disponibilità · '+fmtDate(date),`${field('Stato',select('status',[['yes','Disponibile'],['maybe','In dubbio'],['no','Assente']],r.status||'yes'))}${field('Dalle (facoltativo)',input('from',r.from||'','time'))}${field('Fino alle (facoltativo)',input('to',r.to||'','time'))}`,fd=>saveDay(date,fd.get('status'),fd.get('from'),fd.get('to')));}

function cleanSheets(p){return matchRecords(D,p.id).filter(r=>{const m=match(r.matchId);return m&&(!m.kind||['match','friendly','tournament'].includes(m.kind))&&m.ga===0;}).length;}
function activityMetrics(p,month=''){const days=[...new Set(D.matches.filter(m=>m.date&&m.date<today()&&(!month||m.date.startsWith(month))&&['planned','played'].includes(m.status)).map(m=>m.date))];const rows=days.map(d=>dayResponse(d,p));const yes=rows.filter(r=>r?.status==='yes').length,no=rows.filter(r=>r?.status==='no').length,maybe=rows.filter(r=>r?.status==='maybe').length;const n=days.length,answered=yes+no+maybe;return {n,yes,no,maybe,answered,missing:n-answered,rate:n?Math.round(answered/n*100):null,available:n?Math.round(yes/n*100):null};}
function availabilityMetrics(p){const a=activityMetrics(p),pct=v=>v===null?'—':v+'%';return `<h3>Disponibilità dichiarate</h3><div class="profile-values">${[['Disponibilità',pct(a.available)],['Tasso di risposta',pct(a.rate)],['Giornate di attività',a.n],['Disponibili',a.yes],['Assenti',a.no],['In dubbio',a.maybe],['Non risposto',a.missing]].map(([l,v])=>`<div><small>${l}</small><b>${v}</b></div>`).join('')}</div><small>Solo giornate trascorse con almeno un evento programmato o concluso; una giornata conta una volta. Le assenze dichiarate contano come risposta.</small>`;}
function roleCoverage(m){if(!staff()||!m.date)return '';const ps=activePlayers().filter(p=>response(m,p)?.status==='yes');const groups=[['Portieri',['POR']],['Difensori',['TD','DC','TS','ADA','ASA']],['Centrocampisti',['CDC','CC','COC','ED','ES']],['Attaccanti',['ATT','AS','AD']]];return `<details class="role-coverage"><summary>Copertura ruoli (${ps.length} disponibili)</summary><div class="grid">${groups.map(([label,rs])=>{const natural=ps.filter(p=>rs.some(r=>p.roles?.[r]==='natural'));const adapted=ps.filter(p=>!natural.includes(p)&&rs.some(r=>p.roles?.[r]==='adapted'));return `<div><b>${label}</b><br>${natural.length} naturali · ${adapted.length} adattati${!natural.length&&!adapted.length?' · ⚠ Nessuno':''}</div>`}).join('')}</div><small>Un giocatore può coprire più reparti: i conteggi non sono sommabili.</small></details>`;}
function remindDay(date){if(!staff())return;const missing=activePlayers().filter(p=>dayState(date,p)==='pending');if(!missing.length){toast('Hanno risposto tutti.');return;}const text='⚽ THE BOYS 1927 – Promemoria presenze '+fmtDate(date)+'\nManca la risposta di: '+missing.map(p=>p.name).join(', ')+'\nInserite la disponibilità in Home, grazie!\n'+location.origin+location.pathname;window.open('https://wa.me/?text='+encodeURIComponent(text),'_blank','noopener,noreferrer');}
function showDayHistory(date){if(!staff())return;const rows=(D.availabilityHistory||[]).filter(r=>r.date===date).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)));const desc=r=>r?STATUS[r.status]+(r.from?' dalle '+r.from:'')+(r.to?' fino alle '+r.to:''):'Non risposto';modal('Storico disponibilità · '+fmtDate(date),rows.map(r=>`<div class="panel stack"><b>${esc(player(r.playerId)?.name||'Giocatore')}</b><span>${esc(desc(r.previous))} → ${esc(desc(r.current))}</span><small>${esc(new Date(r.updatedAt).toLocaleString('it-IT'))}</small></div>`).join('')||'<p>Nessuna modifica registrata dalla V2.6.</p>',null);}

function formationShareText(f,m){const pos=FORMATIONS[f.module]||FORMATIONS['4-2-3-1'];return ['⚽ *THE BOYS 1927*',f.status==='approved'?'Formazione ufficiale':'Proposta formazione',m?`${m.opponent} · ${fmtDate(m.date)} ${m.time||''}`:f.name,`Modulo: ${f.module}`,'','*Titolari*',...pos.map(([r],i)=>`${r}: ${player(f.lineup?.[i])?.name||'Da assegnare'}`),'','*Riserve*',...(f.bench||[]).map(id=>player(id)?.name||'Giocatore'),'',...(f.notes?['*Indicazioni tattiche*',f.notes]:[])].join('\n');}
function shortName(name){const s=String(name||'Da assegnare').trim();if(!s)return 'Da assegnare';const parts=s.split(/\s+/).filter(Boolean);let out=parts.length>1?parts[parts.length-1]:parts[0];if(out.length>13&&parts[0])out=parts[0].slice(0,13);return out.length>13?out.slice(0,12)+'…':out;}
function wrapLines(ctx,text,maxWidth){const words=String(text||'').split(/\s+/).filter(Boolean);const lines=[];let line='';for(const word of words){const test=line?line+' '+word:word;if(ctx.measureText(test).width<=maxWidth||!line)line=test;else{lines.push(line);line=word;}}if(line)lines.push(line);return lines.length?lines:[''];}
function roundedRect(ctx,x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.stroke();}}
function loadCanvasImage(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('Impossibile caricare il logo.'));img.src=src;});}
