function splitDayPlans(d){return {...d,dayPlans:d.matches.filter(m=>m.kind==='dayPlan'),matches:d.matches.filter(m=>m.kind!=='dayPlan')};}
function roleColor(r){return r==='POR'?'role-gk':['TD','DC','TS','ADA','ASA'].includes(r)?'role-def':['CDC','CC','COC','ED','ES'].includes(r)?'role-mid':'role-att';}
async function archivePlayer(id){if(!staff())return;const p=player(id);if(!p)return;if(!confirm(p.active===false?'Riattivare il giocatore?':'Archiviare il giocatore conservando tutto lo storico?'))return;await saveOfficial('players',id,{active:p.active===false});document.querySelector('#dialog').close();}
let recordMonth=today().slice(0,7);
function periodStats(p,month=''){const rs=matchRecords(D,p.id).filter(r=>{const m=match(r.matchId);return m&&(!m.kind||['match','friendly','tournament'].includes(m.kind))&&(!month||m.date?.startsWith(month))}).sort((a,b)=>((match(a.matchId)?.date||'')+(match(a.matchId)?.time||'')).localeCompare((match(b.matchId)?.date||'')+(match(b.matchId)?.time||'')));const g=summaryField('gol')?.id,a=summaryField('assist')?.id;const games=rs.map(r=>({date:match(r.matchId)?.date||'',g:Number(r.values?.[g])||0,a:Number(r.values?.[a])||0,c:match(r.matchId)?.ga===0?1:0}));return {n:games.length,g:games.reduce((t,x)=>t+x.g,0),a:games.reduce((t,x)=>t+x.a,0),c:games.reduce((t,x)=>t+x.c,0),games};}
function streak(games,key){let best=0,n=0;for(const x of games){n=x[key]>0?n+1:0;best=Math.max(best,n)}return best;}
function awards(p){const t=periodStats(p),a=activityMetrics(p);return [['📆','Sempre pronto',trophyDate(p,'Sempre pronto')?10:0,10],['⭐','Fuoriclasse',mvpWins(p),5],['⚽','Esordiente',t.n,1],['🏅','Veterano',t.n,25],['👑','Leggenda',t.n,100],['🎯','Cecchino',t.g,10],['🔥','On Fire',streak(t.games,'g'),3],['⚡','Tripletta',Math.max(0,...t.games.map(x=>x.g)),3],['🤝','Assist King',streak(t.games,'a'),3],['🧱','Il Muro',streak(t.games,'c'),3],['🛡️','Porta blindata',t.c,10],['🏆','Saracinesca',t.n>=10?Math.round(t.c/t.n*100):0,50],['📅','Affidabile',a.n>=20?a.rate||0:0,100],['💎','Colonna del club',a.n>=30?a.available||0:0,90],...(D.awardDefinitions||[]).filter(x=>x.active!==false).map(x=>['🏅',x.name,customAwardValue(p,x),x.threshold])];}
function trophyDate(p,name){const saved=(D.earnedAwards||[]).find(x=>x.playerId===p.id&&x.name===name);if(saved)return saved.earnedOn;const custom=(D.awardDefinitions||[]).find(x=>x.name===name);if(custom)return customAwardDate(p,custom);if(name==='Fuoriclasse'){const ms=D.matches.filter(m=>m.status==='played'&&mvpWinners(m).some(x=>x.id===p.id)).sort((a,b)=>a.date.localeCompare(b.date));return ms[4]?.date||'';}if(['Affidabile','Colonna del club','Sempre pronto'].includes(name)){const days=[...new Set(D.matches.filter(m=>m.date&&m.date<today()&&['planned','played'].includes(m.status)).map(m=>m.date))].sort();let yes=0,answers=0,run=0;for(let i=0;i<days.length;i++){const st=dayResponse(days[i],p)?.status;yes+=st==='yes'?1:0;answers+=['yes','no','maybe'].includes(st)?1:0;run=st==='yes'?run+1:0;if((name==='Affidabile'&&i>=19&&answers===i+1)||(name==='Colonna del club'&&i>=29&&yes/(i+1)>=.9)||(name==='Sempre pronto'&&run>=10))return days[i];}return '';}const games=periodStats(p).games;let g=0,a=0,c=0;for(let i=0;i<games.length;i++){const x=games[i];g+=x.g;a+=x.a;c+=x.c;const seq=games.slice(0,i+1);if(({Esordiente:i>=0,Veterano:i>=24,Leggenda:i>=99,Cecchino:g>=10,'On Fire':streak(seq,'g')>=3,Tripletta:x.g>=3,'Assist King':streak(seq,'a')>=3,'Il Muro':streak(seq,'c')>=3,'Porta blindata':c>=10,Saracinesca:i>=9&&c/(i+1)>=.5})[name])return x.date;}return '';}
function achievements(p){return `<div class="award-grid">${awards(p).map(([icon,name,v,n])=>{const date=trophyDate(p,name),ok=v>=n||!!date;return `<div class="award ${ok?'unlocked':''}"><span class="trophy-icon">${icon}</span><b>${esc(name)}</b><small>${ok?'Sbloccato':v+'/'+n}</small>${date?`<small>${fmtDate(date)}</small>`:''}<progress max="${n}" value="${ok?n:Math.min(v,n)}"></progress></div>`;}).join('')}</div>`;}
function recentStreak(games,k){let n=0;for(let i=games.length-1;i>=0&&games[i][k]>0;i--)n++;return n;}
function formBadges(p){const t=periodStats(p),g=t.games.slice(-5),badges=[['🔥','On Fire',recentStreak(t.games,'g')>=3],['🤝','Assist King',recentStreak(t.games,'a')>=3],['🧱','Il Muro',recentStreak(t.games,'c')>=3],['⚡','Decisivo',g.length>=3&&g.slice(-3).reduce((n,x)=>n+x.g+x.a,0)>=5]];return `<div class="line">${badges.filter(x=>x[2]).map(([i,n])=>`<span class="pill">${i} ${n}</span>`).join('')||'<small>Nessun distintivo di forma attivo.</small>'}</div><small>Ultime ${g.length} gare: ${g.reduce((n,x)=>n+x.g,0)} gol · ${g.reduce((n,x)=>n+x.a,0)} assist · ${g.reduce((n,x)=>n+x.c,0)} imbattibilità</small>`;}
let personalMonth=today().slice(0,7);
function personalMonthly(p){const t=periodStats(p,personalMonth),a=activityMetrics(p,personalMonth);return `<input type="month" id="personal-month" value="${esc(personalMonth)}"><div class="profile-values">${[['Presenze',t.n],['Gol',t.g],['Assist',t.a],['Imbattibilità',t.c],['MVP',mvpWins(p,personalMonth)],['Risposte',a.rate===null?'—':a.rate+'%'],['Disponibilità',a.available===null?'—':a.available+'%']].map(([l,v])=>`<div><small>${l}</small><b>${v}</b></div>`).join('')}</div>`;}
document.addEventListener('change',e=>{if(e.target.id==='personal-month'){personalMonth=e.target.value||today().slice(0,7);render()}});
async function activateBuild(id){const p=myPlayer();if(p&&(proData(p).builds||[])[Number(id)]!==undefined)await store.put('profiles',p.id,{activeBuild:Number(id)});}
async function deleteBuild(id){const p=myPlayer();if(!p||!confirm('Rimuovere questa configurazione?'))return;const d=proData(p),builds=[...(d.builds||[])],i=Number(id);builds.splice(i,1);const old=Number(d.activeBuild??-1);await store.put('profiles',p.id,{builds,activeBuild:old===i?-1:old>i?old-1:old});}
function monthlyRecords(){const ps=allPlayers();const metrics=[['Presenze','n'],['Gol','g'],['Assist','a'],['Imbattibilità','c'],['MVP','mvp']];const leaders=(month)=>metrics.map(([label,k])=>{const rows=ps.map(p=>({p,v:k==='mvp'?mvpWins(p,month):periodStats(p,month)[k]}));const max=Math.max(0,...rows.map(r=>r.v));return `<div class="record-tile"><small>${label}</small><strong>${max||'—'}</strong><span>${max?rows.filter(r=>r.v===max).map(r=>esc(r.p.name)).join(' · '):'Nessun dato'}</span></div>`}).join('');return `<section class="panel stack"><h2>Record del mese</h2><input type="month" id="record-month" value="${esc(recordMonth)}"><div class="award-grid">${leaders(recordMonth)}</div><details><summary>Record assoluti del club</summary><div class="award-grid">${leaders('')}</div></details>${trophyBoard()}${staff()?button('+ Traguardo personalizzato','award-edit','','primary'):''}</section>`;}
function objectives(){return top('Obiettivi di squadra','Traguardi condivisi e valutati dallo staff',staff()?button('+ Obiettivo','objective-edit','','primary'):'')+`<section class="stack">${(D.objectives||[]).slice().sort((a,b)=>String(b.month).localeCompare(String(a.month))).map(o=>`<article class="panel stack"><small>${esc(o.month||'')}</small><h2>${esc(o.title)}</h2><p class="prewrap">${esc(o.description||'')}</p><b>${esc(({open:'In corso',done:'Raggiunto',failed:'Non raggiunto'})[o.status]||'In corso')}</b>${o.result?`<p>${esc(o.result)}</p>`:''}${staff()?button('Modifica','objective-edit',o.id):''}</article>`).join('')||empty('Nessun obiettivo inserito.')}</section>`;}
function editObjective(id){if(!staff())return;const o=(D.objectives||[]).find(x=>x.id===id)||{id:uid(),month:today().slice(0,7),status:'open'};modal('Obiettivo squadra',field('Mese',input('month',o.month,'month','required'))+field('Titolo',input('title',o.title||'','text','required maxlength="100"'))+field('Indicazioni',textarea('description',o.description||''))+field('Esito',select('status',[['open','In corso'],['done','Raggiunto'],['failed','Non raggiunto']],o.status))+field('Commento finale',textarea('result',o.result||'')),async fd=>store.put('objectives',o.id,Object.fromEntries(['month','title','description','status','result'].map(k=>[k,String(fd.get(k)||'')]))));}
document.addEventListener('change',e=>{if(e.target.id==='record-month'){recordMonth=e.target.value||today().slice(0,7);render()}});

function publicRecordField(f){return ['gol','assist'].includes(f.name.trim().toLowerCase());}
function isPublicDefinition(f){return f.scope==='player'?publicProField(f):f.scope==='match'&&publicRecordField(f);}
async function saveField(id,value){const old=D.fields.find(f=>f.id===id),v={...old,...value};delete v.id;if(!privacyReady()){await store.put('fields',id,v);return;}const pub=isPublicDefinition(v);if(old&&pub!==isPublicDefinition(old))throw Error('Per modificare la riservatezza di un campo esistente crea un nuovo campo, mantenendo lo storico.');if(pub){if(!old)throw Error('Per un nuovo campo pubblico esegui una revisione delle regole di riservatezza. I nuovi campi personalizzati sono privati.');await store.put('fields',id,v);}else await store.put('privateFields',id,v);}
function privacyReady(){return (D.privacyConfig||[]).some(x=>x.id==='main'&&x.ready===true);}
function mergePrivate(d){if(!staff())return d;d.fields=[...new Map([...(d.fields||[]),...(d.privateFields||[])].map(f=>[f.id,f])).values()];for(const [pub,priv] of [['players','privatePlayers'],['records','privateRecords']]){d[pub]=(d[pub]||[]).map(x=>{const y=(d[priv]||[]).find(v=>v.id===x.id);return y?{...x,notes:y.notes??x.notes,values:{...x.values,...y.values}}:x;});}return d;}
function splitOfficial(c,value){const keys=(D.privacyConfig||[]).find(x=>x.id==='main')?.[c==='players'?'playerKeys':'recordKeys']||D.fields.filter(f=>c==='players'?f.scope==='player'&&publicProField(f):f.scope==='match'&&publicRecordField(f)).map(f=>f.id);const pub={...value},priv={};if('notes' in value){priv.notes=value.notes;pub.notes='';}if('values' in value){pub.values={};priv.values={};for(const [k,v] of Object.entries(value.values||{}))(keys.includes(k)?pub.values:priv.values)[k]=v;}delete pub.id;return [pub,priv];}
async function saveOfficial(c,id,value){await saveOfficialBatch([{c,id,value}]);}
async function saveOfficialBatch(ops){const out=[];for(const op of ops){if(['players','records'].includes(op.c)){const [value,priv]=splitOfficial(op.c,op.value);out.push({...op,value});if(Object.keys(priv).length)out.push({c:op.c==='players'?'privatePlayers':'privateRecords',id:op.id,value:priv});}else out.push(op);}await store.batch(out);}
async function migratePrivacy(){if(!isAdmin())return;if(!confirm('Salvare le valutazioni in area privata e ripulire i documenti pubblici? Durante la migrazione non modificare altri dati.'))return;const playerKeys=D.fields.filter(f=>f.scope==='player'&&publicProField(f)).map(f=>f.id),recordKeys=D.fields.filter(f=>f.scope==='match'&&publicRecordField(f)).map(f=>f.id);const snapshots=['players','records'].map(c=>[c,structuredClone(D[c]||[])]),defs=structuredClone(D.fields||[]);await store.replace('privacyConfig','main',{ready:false,playerKeys,recordKeys});for(const [c,rows] of snapshots){const keys=c==='players'?playerKeys:recordKeys;for(const row of rows){const {id,...rest}=row;const values=rest.values||{},pub={},priv={};for(const [k,v] of Object.entries(values))(keys.includes(k)?pub:priv)[k]=v;await store.put(c==='players'?'privatePlayers':'privateRecords',id,{values:priv,notes:rest.notes||''});await store.replace(c,id,{...rest,values:pub,notes:''});}}for(const f of defs){if(isPublicDefinition(f))continue;const {id,...v}=f;await store.put('privateFields',id,v);await store.remove('fields',id);}await store.replace('privacyConfig','main',{ready:true,playerKeys,recordKeys});toast('Migrazione completata.');}
function participants(m){return allPlayers().filter(p=>D.records.some(r=>r.matchId===m.id&&r.playerId===p.id&&r.appeared!==false));}
function votingButtons(m){const p=myPlayer(),eligible=p&&participants(m).some(x=>x.id===p.id);return `<div class="actions">${staff()&&!m.mvpClosed?button(m.mvpFinalizing?'Completa chiusura MVP':m.mvpOpen?'Chiudi MVP':'Apri MVP','mvp-toggle',m.id):''}${eligible&&m.mvpOpen?button('Vota MVP','mvp-vote',m.id):''}${eligible?button('Autovalutazione','self-vote',m.id):''}</div><small>${m.mvpOpen?'Votazione aperta':m.mvpClosed?'MVP: '+(mvpWinners(m).map(p=>esc(p.name)).join(', ')||'Nessun voto'):'Votazione non aperta'}</small>`;}
function votingList(){const p=myPlayer();return D.matches.filter(m=>m.status==='played'&&p&&participants(m).some(x=>x.id===p.id)).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,20).map(m=>`<div class="notice">${esc(m.opponent)} · ${fmtDate(m.date)}${votingButtons(m)}</div>`).join('')||'Nessuna partita disputata';}
async function toggleMvp(id){if(!staff())return;const m=match(id);if(!m||m.status!=='played')return;if(!m.mvpOpen&&!m.mvpFinalizing){if(m.mvpClosed)return toast('Votazione già conclusa.');await store.put('matches',id,{mvpOpen:true,mvpClosed:false});return;}await store.put('matches',id,{mvpOpen:false,mvpFinalizing:true});const votes=(await store.fresh('mvpVotes')).filter(v=>v.matchId===id),ps=participants(m),counts=ps.map(p=>[p.id,votes.filter(v=>v.target===p.id).length]),max=Math.max(0,...counts.map(x=>x[1]));await store.put('matches',id,{mvpOpen:false,mvpClosed:true,mvpFinalizing:false,mvpWinnerIds:max?counts.filter(x=>x[1]===max).map(x=>x[0]):[],mvpVoteCount:votes.length});toast('Votazione chiusa.');}
async function voteMvp(id){const m=match(id),p=myPlayer();if(!m?.mvpOpen||!p||!participants(m).some(x=>x.id===p.id))return;const ps=participants(m).filter(x=>x.id!==p.id);if(!ps.length)return toast('Nessun candidato.');const key=recordId(id,p.id);if(await store.get('mvpVotes',key))return toast('Hai già votato.');modal('Vota il migliore in campo',field('Compagno',select('target',ps.map(x=>[x.id,x.name]),ps[0].id))+'<small>Un solo voto per partecipante. Gli altri giocatori vedranno solo il risultato finale.</small>',async fd=>store.put('mvpVotes',key,{matchId:id,playerId:p.id,target:String(fd.get('target'))}));}
async function voteSelf(id){const p=myPlayer(),m=match(id);if(!p||m?.status!=='played'||!participants(m).some(x=>x.id===p.id))return;const key=recordId(id,p.id),old=await store.get('selfVotes',key);modal('Autovalutazione riservata allo staff',field('Voto da 1 a 10',input('score',old?.score??7,'number','min="1" max="10" step="1" required'))+field('Commento',textarea('note',old?.note||'','maxlength="1000"')),async fd=>store.put('selfVotes',key,{matchId:id,playerId:p.id,score:Number(fd.get('score')),note:String(fd.get('note'))}));}
function mvpWinners(m){if(!m.mvpClosed)return [];if(Array.isArray(m.mvpWinnerIds))return m.mvpWinnerIds.map(player).filter(Boolean);const votes=(D.mvpVotes||[]).filter(v=>v.matchId===m.id),ps=participants(m),counts=ps.map(p=>[p,votes.filter(v=>v.target===p.id).length]),max=Math.max(0,...counts.map(x=>x[1]));return max?counts.filter(x=>x[1]===max).map(x=>x[0]):[];}
function mvpWins(p,month=''){return D.matches.filter(m=>m.status==='played'&&(!month||m.date?.startsWith(month))&&mvpWinners(m).some(x=>x.id===p.id)).length;}
function safeVideo(v){try{const u=new URL(v);return u.protocol==='https:'?u.href:''}catch{return '';}}
async function approveHighlight(id){if(!staff())return;const h=D.proFeedback.find(x=>x.id===id),url=safeVideo(h?.body);if(!url)throw Error('Serve un link HTTPS valido.');await store.put('highlights',id,{playerId:h.playerId,url,visible:true,createdAt:h.createdAt});}
async function hideHighlight(id){if(staff())await store.remove('highlights',id);}
function highlightList(){return (D.highlights||[]).filter(h=>h.visible&&safeVideo(h.url)).map(h=>`<div class="notice"><b>${esc(player(h.playerId)?.name||'Giocatore')}</b> · <a href="${esc(safeVideo(h.url))}" target="_blank" rel="noopener noreferrer">Guarda highlight</a> ${staff()?button('Nascondi','highlight-hide',h.id):''}</div>`).join('')||'Nessun highlight pubblicato';}
function editPhoto(){const p=myPlayer();if(!p)return;modal('Foto del Pro','<label>Immagine JPG o PNG <input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required></label><small>La foto verrà ridimensionata e sarà visibile ai membri del club.</small>',async fd=>{const file=fd.get('photo');if(!file?.size||file.size>10000000)throw Error('Scegli una foto di massimo 10 MB.');const url=URL.createObjectURL(file);try{const img=await loadCanvasImage(url),c=document.createElement('canvas');c.width=c.height=320;const ctx=c.getContext('2d'),side=Math.min(img.width,img.height);ctx.drawImage(img,(img.width-side)/2,(img.height-side)/2,side,side,0,0,320,320);await store.put('profiles',p.id,{photo:c.toDataURL('image/jpeg',.8)});}finally{URL.revokeObjectURL(url);}});}
function chooseCard(){const p=myPlayer();if(!p)return;const n=awardCount(p),ed=[['Standard',0],['Bronzo',2],['Argento',4],['Oro',6],['Platino',9],['Leggenda',12]];modal('Edizioni Player Card',field('Edizione',select('edition',ed.filter(x=>x[1]<=n).map(x=>[x[0],x[0]]),'Standard'))+field('Azione',select('action',[['download','Scarica PNG'],['share','Condividi immagine']],'download'))+ed.map(([e,k])=>`<div>${e} · ${k} trofei ${n>=k?'✓':'🔒'}</div>`).join(''),async fd=>proCard(String(fd.get('edition')),fd.get('action')==='share'));}


function customAwardValue(p,x){const t=periodStats(p),a=activityMetrics(p);return ({presences:t.n,goals:t.g,assists:t.a,clean:t.c,mvp:mvpWins(p),answers:a.answered})[x.metric]||0;}
function customAwardDate(p,x){if(customAwardValue(p,x)<x.threshold)return '';if(x.metric==='mvp'){const ms=D.matches.filter(m=>mvpWinners(m).some(q=>q.id===p.id)).sort((a,b)=>a.date.localeCompare(b.date));return ms[x.threshold-1]?.date||'';}if(x.metric==='answers'){const days=[...new Set(D.matches.filter(m=>m.date&&m.date<today()&&['planned','played'].includes(m.status)).map(m=>m.date))].sort().filter(d=>dayResponse(d,p));return days[x.threshold-1]||'';}let total=0;for(const g of periodStats(p).games){total+=x.metric==='presences'?1:x.metric==='goals'?g.g:x.metric==='assists'?g.a:g.c;if(total>=x.threshold)return g.date;}return '';}
function editCustomAward(id){if(!staff())return;const old=(D.awardDefinitions||[]).find(x=>x.id===id);modal('Crea traguardo personalizzato',field('Nome distintivo',input('name',old?.name||'','text','required maxlength="60"'))+field('Statistica',select('metric',[['presences','Presenze'],['goals','Gol'],['assists','Assist'],['clean','Imbattibilità'],['mvp','MVP'],['answers','Risposte alle giornate di attività']],old?.metric||'presences'))+field('Soglia',input('threshold',old?.threshold||10,'number','min="1" max="10000" step="1" required')),async fd=>{const name=String(fd.get('name')).trim(),threshold=Number(fd.get('threshold'));if(!name||!Number.isInteger(threshold)||threshold<1)throw Error('Nome e soglia obbligatori.');if(allPlayers().some(p=>awards(p).some(x=>x[1]===name))||(D.awardDefinitions||[]).some(x=>x.name===name))throw Error('Nome già utilizzato.');await store.put('awardDefinitions',uid(),{name,metric:fd.get('metric'),threshold,active:true});});}
function awardCount(p){return new Set([...awards(p).filter(x=>x[2]>=x[3]||trophyDate(p,x[1])).map(x=>x[1]),...(D.earnedAwards||[]).filter(x=>x.playerId===p.id).map(x=>x.name)]).size;}
function trophyBoard(){const ps=allPlayers().map(p=>({p,n:awardCount(p)})).sort((a,b)=>b.n-a.n||sortName(a.p,b.p));const recent=(D.earnedAwards||[]).slice().sort((a,b)=>String(b.earnedOn).localeCompare(String(a.earnedOn))).slice(0,8);return `<details><summary>Classifica trofei del club</summary>${table(['Giocatore','Trofei'],ps.map(x=>[esc(x.p.name),x.n]))}<h3>Ultimi trofei registrati</h3>${recent.map(x=>`<div>🏅 ${esc(player(x.playerId)?.name||'Giocatore')} · ${esc(x.name)} · ${fmtDate(x.earnedOn)}</div>`).join('')||'Nessun trofeo registrato'}</details>`;}
let awardBusy=false;
async function reconcileAwards(){if(!staff()||awardBusy||(!demo&&!privacyReady()))return;awardBusy=true;try{const ops=[];for(const p of allPlayers()){for(const [,name,v,n] of awards(p)){const date=trophyDate(p,name);if(!date|| (D.earnedAwards||[]).some(x=>x.playerId===p.id&&x.name===name))continue;ops.push({id:p.id+'_'+encodeURIComponent(name),value:{playerId:p.id,name,earnedOn:date}});}}for(const op of ops){try{await store.put('earnedAwards',op.id,op.value);}catch(e){console.warn('Registrazione trofeo',e.message);}}}finally{awardBusy=false;}}

const err=e=>{if(!staff()&&profile?.role==='player'&&e.code==='permission-denied'){loginScreen('Aggiornamento riservatezza in corso.',button('Esci','logout'),'Attendi che l’amministratore completi la migrazione oppure contattalo se il problema persiste.');return;}toast(e.message||String(e),true);if(loading)loginScreen('Errore di collegamento al database.',button('Esci','logout'),e.message||String(e));};
async function boot(){if(demo){store=demoStore();profile={id:'demo',name:'Amministratore demo',role:'admin',playerId:'p1'};store.listen(d=>{D=mergePrivate(splitDayPlans(d));loading=false;render();reconcileAwards()});return}if(!configured()){loginScreen('Il portale non è ancora configurato.','<a class="btn primary" href="?demo=1">Prova il portale</a>','Configura Firebase seguendo la guida inclusa nel progetto.');return}try{store=await cloudStore();store.authWatch(async u=>{const token=++session;++dataSession;document.querySelector('#dialog').close();offProfile?.();offData?.();profile=null;D={};loading=true;user=u;view='home';if(!u){loginScreen('Area riservata alla squadra.',button('Accedi con Google','login','','primary'));return}root.innerHTML='<div class="loading">Verifica accesso…</div>';try{await store.ensureProfile(u);if(token!==session)return;offProfile=store.profileWatch(u.uid,p=>{if(token!==session)return;const previous=profile;profile=p;if(previous?.role!==p?.role)document.querySelector('#dialog').close();if(!canAccess()){++dataSession;offData?.();offData=null;loading=true;D={};loginScreen('Richiesta di accesso registrata.',button('Esci','logout'),'Attendi che un amministratore abiliti il tuo account.');return}if(previous?.role===p.role&&offData){render();return}offData?.();const ds=++dataSession;loading=true;root.innerHTML='<div class="loading">Caricamento dati del club…</div>';const names=COLLECTIONS.filter(k=>k!=='proFeedback'||staff()).filter(k=>k!=='users'||isAdmin()).filter(k=>!['staffNotes','availabilityHistory','selfVotes','privatePlayers','privateRecords','privateFields','mvpVotes'].includes(k)||staff());offData=store.listen(names,d=>{if(token!==session||ds!==dataSession)return;D=mergePrivate(splitDayPlans(d));loading=false;render();reconcileAwards()},err);},err)}catch(e){err(e)}})}catch(e){loginScreen('Impossibile inizializzare Firebase.','',e.message||String(e))}}boot();